            const hp0 = @typeInfo(h_info.params[0].type.?);
            if (comptime ((hp0 == .pointer) and (!hp0.pointer.is_const))) {
                return T.hash((blk: {
                break :blk @constCast(val);

}), hasher);
            }
            return T.hash(val, hasher);
        }
});
}
